changeSet.sql:
DO $$
BEGIN
    EXECUTE format('ALTER DATABASE %I SET timezone TO %L', current_database(), 'America/Bogota');
END
$$;

rollback.sql:
DO $$
BEGIN
    EXECUTE format('ALTER DATABASE %I RESET timezone', current_database());
END
$$;

DO $$
BEGIN
    DROP EXTENSION IF EXISTS vector;
EXCEPTION WHEN insufficient_privilege THEN
    RAISE NOTICE 'Extension vector kept: it belongs to the administrator role';
END
$$;
